import{c as t,Q as o,j as a,m as n}from"./chunks/framework.g_l1frA7.js";const u=JSON.parse('{"title":"Budget","description":"","frontmatter":{},"headers":[],"relativePath":"guide/budget.md","filePath":"guide/budget.md","lastUpdated":null}'),s={name:"guide/budget.md"};function r(i,e,l,d,h,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="budget" tabindex="-1">Budget <a class="header-anchor" href="#budget" aria-label="Permalink to &quot;Budget&quot;">​</a></h1><p>Envelope planning — decide what each dollar is for before the month spends it.</p><h2 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h2><ul><li><strong>Envelope</strong> — a category with a budgeted amount for the month. Budgets live in <code>crates/finsight-core::repos/budgets</code>.</li><li><strong>To Budget</strong> — income assigned vs unassigned. When To Budget is negative, you have planned more than you have.</li><li><strong>Carryover</strong> — unspent envelope amount that rolls to next month. Configure per envelope; useful for groceries, not for “guilt-free” where you want a reset.</li><li><strong>Conscious Spending allocation</strong> — every category is tagged as Need / Want / Saving / Investment. Budget shows the allocation donut and flags when wants creep past needs (Sethi).</li></ul><h2 id="planning-a-month" tabindex="-1">Planning a month <a class="header-anchor" href="#planning-a-month" aria-label="Permalink to &quot;Planning a month&quot;">​</a></h2><ol><li>Open <strong>Budget</strong> and pick the month.</li><li>Set an amount per envelope. The “To Budget” header counts down.</li><li>Adjust until To Budget is 0 or positive with Savings ≥10% of income.</li><li>During the month, each envelope shows spent / budgeted, with a thin progress bar. Extra spend pulls from To Budget, not from other envelopes, unless you move it.</li><li>At month close, carryover is applied per envelope per <code>repos/month_close</code>.</li></ol><h2 id="per-person-scope" tabindex="-1">Per-person scope <a class="header-anchor" href="#per-person-scope" aria-label="Permalink to &quot;Per-person scope&quot;">​</a></h2><p>Households can scope the “spent” side to one member’s ownership-weighted share via the scope pills. Budgets themselves stay household-level — only actuals are rescoped.</p><h2 id="budget-vs-forecast" tabindex="-1">Budget vs forecast <a class="header-anchor" href="#budget-vs-forecast" aria-label="Permalink to &quot;Budget vs forecast&quot;">​</a></h2><p>The “forecast” card shows deterministic end-of-month projection from burn rate and planned transactions. It is math from <code>finsight-core::forecast</code>, explained by the Copilot — not an LLM guess.</p><h2 id="keyboard-accessibility" tabindex="-1">Keyboard &amp; accessibility <a class="header-anchor" href="#keyboard-accessibility" aria-label="Permalink to &quot;Keyboard &amp; accessibility&quot;">​</a></h2><p>Envelopes are not draggable cards — the primary control is the amount input inside each row. The whole-budget grid lifts subtly on hover for reading focus, not to imply “this row is clickable”.</p><p>See also: <a href="/FinSight/guide/categories">Categories</a>, <a href="/FinSight/guide/cashflow">Cash Flow</a>, <a href="/FinSight/guide/scenarios">Scenarios</a>.</p>',13)])])}const g=t(s,[["render",r]]);export{u as __pageData,g as default};
